(text, request, material) => { const m = text.match(/(^|
)##\s*Coverage analysis\s*
([\s\S]*?)(?=
##\s|$)/i); if (!m) return null; const body = m[2]; const hasClause = /clause\s+\d+(\.\d+)?/i.test(body); const hasPolicy = /\[[^\]]*policy[^\]]*\]/i.test(body); const ok = hasClause && hasPolicy; return { ok, detail: ok ? 'coverage conclusion cites a clause and the policy' : 'coverage analysis lacks a cited policy clause', spans: ok ? [] : [{start: text.indexOf(body), end: text.indexOf(body)+body.length, why: 'no clause number and policy citation'}] }; }
